function getDadosAcumulados(dadosPorData) {
  var sum = {};
  EMPRESAS.forEach(function(emp) {
    sum[emp.id] = { monitor: 0, prenota: 0, robo: 0, total: 0 };
  });
  DAY_KEYS.forEach(function(d) {
    EMPRESAS.forEach(function(emp) {
      var dayData = dadosPorData[d]?.[emp.id];
      if (dayData) {
        sum[emp.id].monitor += dayData.monitor;
        sum[emp.id].prenota += dayData.prenota;
        sum[emp.id].robo += dayData.robo;
        sum[emp.id].total += dayData.total;
      }
    });
  });
  return sum;
}

function getDadosParaEmpresa(dados, empresaId) {
  return dados && dados[empresaId] ? dados[empresaId] : { monitor: 0, prenota: 0, robo: 0, total: 0 };
}

function getDadosMaasPorPessoa(dados, personId) {
  var empresaData = dados && dados['maas'] ? dados['maas'] : { monitor: 0, prenota: 0, robo: 0, total: 0 };
  if (personId === 'all') return empresaData;
  if (empresaData[personId]) return empresaData[personId];
  var share = getMaasPersonShare(personId);
  return {
    monitor: Math.round(empresaData.monitor * share),
    prenota: Math.round(empresaData.prenota * share),
    robo: Math.round(empresaData.robo * share),
    total: Math.round(empresaData.total * share)
  };
}

function getTotaisGeral(dados) {
  var totalMonitor = 0, totalPrenota = 0, totalRobo = 0;
  EMPRESAS.forEach(function(emp) {
    var d = dados[emp.id];
    if (d) {
      totalMonitor += d.monitor;
      totalPrenota += d.prenota;
      totalRobo += d.robo;
    }
  });
  return {
    geral: totalMonitor + totalPrenota,
    totalMonitor: totalMonitor,
    totalPrenota: totalPrenota,
    totalRobo: totalRobo
  };
}

function getTotalData(dadosPorData, data) {
  var dayData = dadosPorData[data];
  if (!dayData) return 0;
  return Object.values(dayData).reduce(function(s, e) { return s + e.total; }, 0);
}

function getValorDiaContexto(dadosPorData, data, pagina) {
  var dayData = dadosPorData[data];
  if (!dayData) return 0;
  if (pagina === 'geral') {
    return Object.values(dayData).reduce(function(s, e) { return s + e.total; }, 0);
  }
  return dayData[pagina]?.total || 0;
}

function getTotalGeralAcumulado(dadosPorData) {
  return DAY_KEYS.reduce(function(sum, d) { return sum + getTotalData(dadosPorData, d); }, 0);
}

function parseDateNumeric(dateStr) {
  var parts = dateStr.split('/');
  return parseInt(parts[0]) + parseInt(parts[1]) * 100;
}

function getRangeAcumulado(startStr, endStr) {
  var startNum = parseDateNumeric(startStr);
  var endNum = parseDateNumeric(endStr);
  var sum = {};
  EMPRESAS.forEach(function(emp) {
    sum[emp.id] = { monitor: 0, prenota: 0, robo: 0, total: 0 };
    var c = getCompany(emp.id);
    if (c && c.responsaveis) {
      c.responsaveis.forEach(function(p) { sum[emp.id][p.id] = { monitor: 0, prenota: 0, robo: 0, total: 0 }; });
    }
  });
  var reg = DATA_REGISTRY[2026];
  for (var mk in reg) {
    if (!reg.hasOwnProperty(mk)) continue;
    var mData = reg[mk];
    for (var wn in mData.weeks) {
      if (!mData.weeks.hasOwnProperty(wn)) continue;
      var week = mData.weeks[wn];
      for (var dk in week.calendar.dias) {
        if (!week.calendar.dias.hasOwnProperty(dk)) continue;
        var dateNum = parseDateNumeric(week.calendar.dias[dk].display);
        if (dateNum >= startNum && dateNum <= endNum) {
          var dayData = week.data[dk];
          EMPRESAS.forEach(function(emp) {
            var dd = dayData[emp.id];
            if (dd) {
              sum[emp.id].monitor += dd.monitor;
              sum[emp.id].prenota += dd.prenota;
              sum[emp.id].robo += dd.robo;
              sum[emp.id].total += dd.total;
              var c = getCompany(emp.id);
              if (c && c.responsaveis) {
                c.responsaveis.forEach(function(p) {
                  if (dd[p.id]) {
                    sum[emp.id][p.id].monitor += dd[p.id].monitor || 0;
                    sum[emp.id][p.id].prenota += dd[p.id].prenota || 0;
                    sum[emp.id][p.id].robo += dd[p.id].robo || 0;
                    sum[emp.id][p.id].total += dd[p.id].total || 0;
                  }
                });
              }
            }
          });
        }
      }
    }
  }
  return sum;
}

function getMaasPersonMetrics(dados, personId) {
  var data = getDadosMaasPorPessoa(dados, personId);
  return {
    total: data.total,
    monitor: data.monitor,
    prenota: data.prenota,
    robo: data.robo,
    eficiencia: data.monitor > 0 ? ((data.robo / data.monitor) * 100).toFixed(1) : 0,
    pctPrenota: data.total > 0 ? ((data.prenota / data.total) * 100).toFixed(1) : 0
  };
}

function getRangeDiario(startStr, endStr) {
  var startNum = parseDateNumeric(startStr);
  var endNum = parseDateNumeric(endStr);
  var days = [];
  var reg = DATA_REGISTRY[2026];
  for (var mk in reg) {
    if (!reg.hasOwnProperty(mk)) continue;
    var mData = reg[mk];
    for (var wn in mData.weeks) {
      if (!mData.weeks.hasOwnProperty(wn)) continue;
      var week = mData.weeks[wn];
      for (var dk in week.calendar.dias) {
        if (!week.calendar.dias.hasOwnProperty(dk)) continue;
        var dateStr = week.calendar.dias[dk].display;
        var dateNum = parseDateNumeric(dateStr);
        if (dateNum >= startNum && dateNum <= endNum) {
          var dayData = week.data[dk];
          var monitor = 0, prenota = 0, robo = 0;
          EMPRESAS.forEach(function(emp) {
            var dd = dayData ? dayData[emp.id] : null;
            if (dd) { monitor += dd.monitor; prenota += dd.prenota; robo += dd.robo; }
          });
          days.push({ dateStr: dateStr, dateNum: dateNum, monitor: monitor, prenota: prenota, robo: robo, gap: Math.max(0, monitor - robo) });
        }
      }
    }
  }
  days.sort(function(a, b) { return a.dateNum - b.dateNum; });
  return days;
}

function getPrevPeriodTotals(startStr, endStr) {
  var sParts = startStr.split('/');
  var eParts = endStr.split('/');
  var startDate = new Date(2026, parseInt(sParts[1]) - 1, parseInt(sParts[0]));
  var endDate = new Date(2026, parseInt(eParts[1]) - 1, parseInt(eParts[0]));
  var diffDays = Math.round((endDate - startDate) / 86400000) + 1;
  var prevEnd = new Date(startDate);
  prevEnd.setDate(prevEnd.getDate() - 1);
  var prevStart = new Date(prevEnd);
  prevStart.setDate(prevStart.getDate() - diffDays + 1);
  function fmt(d) { return (d.getDate() < 10 ? '0' : '') + d.getDate() + '/' + (d.getMonth() + 1 < 10 ? '0' : '') + (d.getMonth() + 1); }
  return getRangeAcumulado(fmt(prevStart), fmt(prevEnd));
}

function getWeeklyTrends(maxWeeks) {
  maxWeeks = maxWeeks || 12;
  var weeks = [];
  var reg = DATA_REGISTRY[2026];
  var monthNamesShort = { '5': 'mai', '6': 'jun', '7': 'jul', '8': 'ago', '9': 'set', '10': 'out', '11': 'nov', '12': 'dez' };
  var allMonths = Object.keys(reg).sort(function(a, b) {
    return reg[a].monthNum - reg[b].monthNum;
  });
  for (var mi = 0; mi < allMonths.length; mi++) {
    var mk = allMonths[mi];
    var mData = reg[mk];
    var weekNums = Object.keys(mData.weeks).map(Number).sort(function(a, b) { return a - b; });
    for (var wi = 0; wi < weekNums.length; wi++) {
      var wn = weekNums[wi];
      var week = mData.weeks[wn];
      var monitor = 0, prenota = 0, robo = 0, hasData = false;
      for (var dk in week.data) {
        if (!week.data.hasOwnProperty(dk)) continue;
        EMPRESAS.forEach(function(emp) {
          var dd = week.data[dk] ? week.data[dk][emp.id] : null;
          if (dd && dd.total > 0) {
            monitor += dd.monitor; prenota += dd.prenota; robo += dd.robo; hasData = true;
          }
        });
      }
      if (hasData) {
        var diasVals = Object.values(week.calendar.dias);
        var label = diasVals.length > 0 ? diasVals[0].display : 'S' + wn;
        var lp = label.split('/');
        var labelFmt = lp[0] + '/' + (monthNamesShort[String(parseInt(lp[1]))] || lp[1]);
        weeks.push({ weekNum: wn, label: labelFmt, monitor: monitor, prenota: prenota, robo: robo, total: monitor + prenota });
      }
    }
  }
  return weeks.slice(0, maxWeeks);
}

:root {
  --navy: #0F1B4A;
  --navy-mid: #1B2A6E;
  --navy-light: #EEF0FA;
  --orange: #FF6B35;
  --orange-light: #FFF0EB;
  --green: #059669;
  --green-mid: #2E7D32;
  --green-light: #ECFDF5;
  --amber: #ED6C02;
  --amber-light: #FFF3E0;
  --purple: #7C3AED;
  --purple-light: #F5F3FF;
  --red: #DC2626;
  --red-light: #FEF2F2;
  --blue: #2563EB;
  --blue-light: #EFF6FF;
  --gray-50: #F8FAFC;
  --gray-100: #F1F5F9;
  --gray-200: #E2E8F0;
  --gray-300: #CBD5E1;
  --gray-400: #94A3B8;
  --gray-500: #64748B;
  --gray-600: #475569;
  --gray-700: #334155;
  --gray-800: #1E293B;
  --gray-900: #0F172A;
  --white: #FFFFFF;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.04);
  --shadow: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -1px rgba(0,0,0,0.04);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -2px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 10px 10px -5px rgba(0,0,0,0.04);
  --radius-sm: 4px;
  --radius: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --transition: 200ms cubic-bezier(0.4, 0, 0.2, 1);
  --sidebar-width: 240px;
  --sidebar-collapsed: 60px;
  --topbar-height: 60px;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
html, body { height: 100%; }
body {
  font-family: var(--font);
  background: var(--gray-100);
  color: var(--gray-900);
  display: flex;
  min-height: 100vh;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

/* SIDEBAR */
.sidebar {
  width: var(--sidebar-width);
  background: #0F1B4A;
  color: var(--white);
  display: flex;
  flex-direction: column;
  flex-shrink: 0;
  transition: width var(--transition);
  overflow: hidden;
  z-index: 100;
  position: fixed;
  top: 0; left: 0;
  height: 100vh;
}
body.sidebar-collapsed .sidebar { width: var(--sidebar-collapsed); }

.sidebar-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 14px 12px;
  border-bottom: 1px solid rgba(255,255,255,0.07);
  min-height: 60px;
}
.sidebar-toggle {
  background: none; border: none;
  color: rgba(255,255,255,0.45);
  cursor: pointer; padding: 5px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  transition: color var(--transition), background var(--transition);
}
.sidebar-toggle:hover { color: var(--white); background: rgba(255,255,255,0.1); }
.sidebar-logo { overflow: hidden; white-space: nowrap; }
.logo-marca {
  font-size: 13px; font-weight: 800;
  letter-spacing: -0.01em; color: var(--white);
  text-transform: uppercase;
}
.logo-marca span { color: var(--orange); }
.logo-sub {
  font-size: 9px; color: rgba(255,255,255,0.35);
  margin-top: 1px; font-weight: 400; text-transform: uppercase; letter-spacing: 0.05em;
}
body.sidebar-collapsed .sidebar-logo { display: none; }
body.sidebar-collapsed .sidebar-header { justify-content: center; padding: 16px 8px; }
body.sidebar-collapsed .sidebar-toggle { margin: 0 auto; }

/* NAV */
.sidebar-nav { flex: 1; padding: 10px 0; overflow-y: auto; }
.sidebar-nav::-webkit-scrollbar { width: 3px; }
.sidebar-nav::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 2px; }

.nav-label {
  font-size: 9px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.12em; color: rgba(255,255,255,0.28);
  padding: 14px 14px 4px;
  white-space: nowrap;
}
body.sidebar-collapsed .nav-label { display: none; }

.nav-item {
  display: flex; align-items: center; gap: 10px;
  padding: 8px 14px 8px 11px;
  color: rgba(255,255,255,0.5);
  cursor: pointer;
  transition: all var(--transition);
  font-size: 13px; font-weight: 400;
  white-space: nowrap; overflow: hidden;
  border-left: 3px solid transparent;
  position: relative;
}
.nav-item:hover { color: var(--white); background: rgba(255,255,255,0.06); }
.nav-item.active {
  color: var(--white); background: rgba(255,107,53,0.15);
  border-left-color: var(--orange); font-weight: 600;
}
.nav-icon {
  flex-shrink: 0; width: 18px; height: 18px;
  display: flex; align-items: center; justify-content: center; opacity: 0.65;
}
.nav-item.active .nav-icon { opacity: 1; }
.nav-text { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.nav-badge {
  background: var(--red); color: white;
  font-size: 10px; font-weight: 700;
  border-radius: 100px; padding: 1px 6px;
  min-width: 18px; text-align: center;
  flex-shrink: 0;
}
.nav-company-icon {
  width: 22px; height: 22px; border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  font-size: 9px; font-weight: 800; color: white;
  flex-shrink: 0; letter-spacing: -0.5px;
}
body.sidebar-collapsed .nav-text,
body.sidebar-collapsed .nav-label,
body.sidebar-collapsed .nav-badge { display: none; }
body.sidebar-collapsed .nav-item { justify-content: center; padding: 10px; border-left: none; }
body.sidebar-collapsed .nav-item .nav-icon { width: 20px; height: 20px; opacity: 0.7; }
body.sidebar-collapsed .nav-company-icon { width: 24px; height: 24px; font-size: 10px; }
body.sidebar-collapsed .nav-item.active { background: rgba(255,107,53,0.2); border-radius: var(--radius-sm); }

/* SIDEBAR FOOTER */
.sidebar-footer {
  padding: 12px 14px; border-top: 1px solid rgba(255,255,255,0.07);
  font-size: 10px; color: rgba(255,255,255,0.25); line-height: 1.5;
  white-space: nowrap; overflow: hidden;
}
.footer-period-label { font-size: 9px; text-transform: uppercase; letter-spacing: 0.08em; color: rgba(255,255,255,0.2); }
.footer-period-value { font-size: 11px; font-weight: 600; color: rgba(255,255,255,0.55); margin: 2px 0; }
.footer-updated { font-size: 9px; color: rgba(255,255,255,0.2); }
body.sidebar-collapsed .sidebar-footer { display: none; }

/* SIDEBAR FILTERS (hidden — period is now in topbar) */
.sidebar-filters { display: none; }

/* MAIN */
.main {
  margin-left: var(--sidebar-width);
  flex: 1; min-height: 100vh;
  display: flex; flex-direction: column;
  transition: margin-left var(--transition);
}
body.sidebar-collapsed .main { margin-left: var(--sidebar-collapsed); }

/* TOPBAR */
.topbar {
  height: var(--topbar-height);
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  display: flex; align-items: center; justify-content: space-between;
  padding: 0 24px;
  position: sticky; top: 0; z-index: 50;
  gap: 16px;
}
.topbar-left { display: flex; align-items: center; gap: 16px; min-width: 0; }
.topbar-left h1 { font-size: 18px; font-weight: 700; color: var(--gray-900); letter-spacing: -0.03em; }
.topbar-left p { font-size: 11px; color: var(--gray-400); margin-top: 1px; }
.topbar-right { display: flex; align-items: center; gap: 8px; flex-shrink: 0; }

/* BUTTONS */
.btn-primary {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 6px 12px; font-size: 12px; font-weight: 500;
  font-family: var(--font);
  border: 1px solid var(--gray-200); background: var(--white);
  color: var(--gray-600); border-radius: 6px; cursor: pointer;
  transition: all var(--transition);
}
.btn-primary:hover { background: var(--gray-50); border-color: var(--gray-300); color: var(--gray-800); }
.btn-primary svg { flex-shrink: 0; }
.btn-success { background: var(--green); border-color: var(--green); color: var(--white); }
.btn-success:hover { background: #047857; border-color: #047857; }
.btn-sm { padding: 4px 10px; font-size: 11px; }
.btn-date-range {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 6px 13px; font-size: 12px; font-weight: 500;
  font-family: var(--font);
  border: 1px solid var(--gray-200); background: var(--white);
  color: var(--gray-700); border-radius: 6px; cursor: pointer;
  transition: all var(--transition);
}
.btn-date-range:hover { background: var(--gray-50); border-color: var(--gray-300); }
.btn-link {
  background: none; border: none; cursor: pointer;
  font-size: 11px; font-weight: 500; color: var(--blue);
  font-family: var(--font); padding: 0;
  transition: opacity var(--transition);
}
.btn-link:hover { opacity: 0.7; }

/* CONTENT */
.content { flex: 1; padding: 20px 24px; }
.page { display: none; }
.page.active { display: block; }

/* PANELS */
.panel {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-md); padding: 18px;
  box-shadow: var(--shadow-sm); overflow: hidden;
}
.panel-header {
  display: flex; align-items: center; justify-content: space-between;
  margin-bottom: 16px;
}
.panel-header h3 {
  font-size: 11px; font-weight: 700; color: var(--gray-600);
  text-transform: uppercase; letter-spacing: 0.07em;
}

/* GRID LAYOUTS */
.dashboard-grid-2 {
  display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 14px;
}
.dashboard-grid-destaques {
  display: grid; grid-template-columns: 1fr 380px; gap: 14px; margin-bottom: 14px;
}

/* PERSON SELECTOR */
.person-selector {
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 16px; padding: 10px 14px;
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-md); box-shadow: var(--shadow-sm);
}
.person-selector .ps-label {
  font-size: 10px; font-weight: 600; color: var(--gray-500);
  text-transform: uppercase; letter-spacing: 0.05em; margin-right: 4px;
}
.person-btn {
  padding: 4px 13px; font-size: 12px; font-weight: 500;
  font-family: var(--font); border: 1px solid var(--gray-200);
  background: var(--white); color: var(--gray-600);
  border-radius: 100px; cursor: pointer; transition: all var(--transition);
}
.person-btn:hover { border-color: var(--gray-300); background: var(--gray-50); }
.person-btn.active { background: var(--navy-light); border-color: var(--navy); color: var(--navy); font-weight: 600; }

/* CARDS (company pages) */
.cards {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-bottom: 16px;
}
.card {
  background: var(--white); border: 1px solid var(--gray-200);
  border-radius: var(--radius-md); padding: 0;
  box-shadow: var(--shadow-sm); overflow: hidden;
}
.card-accent { height: 3px; width: 100%; }
.card-title { font-size: 10px; font-weight: 600; color: var(--gray-500); padding: 12px 14px 0; text-transform: uppercase; letter-spacing: 0.05em; }
.card-value { font-size: 28px; font-weight: 800; color: var(--gray-900); letter-spacing: -0.03em; line-height: 1.1; padding: 2px 14px; }
.card-sub { font-size: 10px; color: var(--gray-400); padding: 2px 14px 12px; }
.card-badge {
  display: inline-block; font-size: 11px; font-weight: 600;
  padding: 2px 8px; border-radius: 100px; margin: 2px 14px 12px;
}

/* INSIGHT */
.insight {
  background: var(--navy-light); border-radius: var(--radius-md);
  padding: 11px 16px; font-size: 12px; line-height: 1.55;
  color: var(--navy); margin-bottom: 16px;
}
.insight strong { font-weight: 600; }

/* GRID */
.grid2 { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 16px; }

/* PROGRESS BARS */
.prog-row { display: flex; align-items: center; gap: 10px; margin-bottom: 8px; }
.prog-row:last-child { margin-bottom: 0; }
.prog-label { font-size: 11px; color: var(--gray-600); width: 180px; flex-shrink: 0; }
.prog-wrap { flex: 1; height: 6px; background: var(--gray-100); border-radius: 100px; overflow: hidden; }
.prog-fill { height: 100%; border-radius: 100px; transition: width 0.5s ease; }
.prog-val { font-size: 12px; font-weight: 600; color: var(--gray-700); width: 28px; text-align: right; }
.prog-pct { font-size: 11px; font-weight: 500; color: var(--gray-400); width: 40px; text-align: right; }

/* TABLE */
table { width: 100%; border-collapse: collapse; font-size: 12px; }
table thead th {
  text-align: left; padding: 7px 9px;
  font-weight: 600; color: var(--gray-500); font-size: 10px;
  text-transform: uppercase; letter-spacing: 0.04em;
  border-bottom: 1px solid var(--gray-200);
}
table tbody td { padding: 7px 9px; border-bottom: 1px solid var(--gray-100); color: var(--gray-700); }
table tbody tr:last-child td { border-bottom: none; }
table tbody tr:hover { background: var(--gray-50); }
table .num { text-align: right; font-variant-numeric: tabular-nums; }
table .table-total td { background: var(--gray-50); font-weight: 600; color: var(--gray-900); border-bottom: 2px solid var(--gray-300); }

/* RANKING */
.rank-item { display: flex; align-items: center; gap: 12px; padding: 8px 0; border-bottom: 1px solid var(--gray-100); }
.rank-item:last-child { border-bottom: none; }
.rank-num { width: 22px; height: 22px; border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 700; color: var(--gray-400); background: var(--gray-100); flex-shrink: 0; }
.rank-item:first-child .rank-num { background: #FEF3C7; color: #B45309; }
.rank-item:nth-child(2) .rank-num { background: var(--gray-200); color: var(--gray-600); }
.rank-item:nth-child(3) .rank-num { background: var(--red-light); color: var(--red); }
.rank-info { flex: 1; min-width: 0; }
.rank-name { font-size: 12px; font-weight: 600; color: var(--gray-800); }
.rank-sub { font-size: 10px; color: var(--gray-400); margin-top: 1px; }
.rank-val { font-size: 17px; font-weight: 700; color: var(--gray-900); }

/* TOAST */
.toast {
  position: fixed; bottom: 20px; right: 20px;
  background: var(--gray-900); color: var(--white);
  padding: 10px 16px; border-radius: var(--radius);
  font-size: 13px; font-weight: 500; box-shadow: var(--shadow-lg);
  display: none; z-index: 10000;
  animation: toastIn 0.3s ease; max-width: 320px;
}
@keyframes toastIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

/* PERSON METRICS */
.person-metrics { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 16px; }
.person-metric { background: var(--white); border: 1px solid var(--gray-200); border-radius: var(--radius-md); padding: 12px 14px; box-shadow: var(--shadow-sm); text-align: center; }
.person-metric .pm-label { font-size: 9px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.05em; color: var(--gray-400); margin-bottom: 3px; }
.person-metric .pm-value { font-size: 22px; font-weight: 700; color: var(--gray-900); line-height: 1.2; }
.person-metric .pm-sub { font-size: 10px; color: var(--gray-400); margin-top: 1px; }

/* CALENDAR MODAL */
.cal-modal-overlay { display: none; position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.45); z-index: 9999; align-items: center; justify-content: center; }
.cal-modal-overlay.open { display: flex; }
.cal-modal { background: var(--white); border-radius: var(--radius-lg); box-shadow: 0 20px 60px rgba(0,0,0,0.25); width: 340px; max-width: 90vw; padding: 20px 20px 14px; animation: calFadeIn 0.2s ease; }
@keyframes calFadeIn { from { opacity: 0; transform: scale(0.96) translateY(8px); } to { opacity: 1; transform: scale(1) translateY(0); } }
.cal-modal-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px; }
.cal-modal-title { font-size: 14px; font-weight: 600; color: var(--gray-900); }
.cal-nav-btn { background: none; border: none; color: var(--gray-400); cursor: pointer; width: 28px; height: 28px; border-radius: 6px; display: flex; align-items: center; justify-content: center; transition: all var(--transition); }
.cal-nav-btn:hover { background: var(--gray-100); color: var(--gray-700); }
.calendar-period-selector { margin-bottom: 10px; }
.period-presets { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 8px; }
.period-btn { padding: 4px 9px; font-size: 10px; font-weight: 500; font-family: var(--font); border: 1px solid var(--gray-200); background: var(--white); color: var(--gray-500); border-radius: 100px; cursor: pointer; transition: all var(--transition); }
.period-btn:hover { border-color: var(--gray-300); background: var(--gray-50); color: var(--gray-700); }
.period-btn.active { background: var(--navy-light); border-color: var(--navy); color: var(--navy); font-weight: 600; }
.period-custom { display: none; align-items: center; gap: 6px; padding: 7px 9px; background: var(--gray-50); border: 1px solid var(--gray-200); border-radius: var(--radius); margin-bottom: 7px; }
.period-custom.open { display: flex; flex-wrap: wrap; }
.period-custom label { font-size: 10px; font-weight: 500; color: var(--gray-500); }
.period-custom input[type="date"] { font-family: var(--font); font-size: 11px; padding: 3px 6px; border: 1px solid var(--gray-200); border-radius: 5px; color: var(--gray-700); background: var(--white); }
.period-custom input[type="date"]:focus { outline: none; border-color: var(--navy); }
.period-info { font-size: 10px; color: var(--gray-500); margin-bottom: 7px; font-weight: 500; }
.cal-modal-table { width: 100%; table-layout: fixed; border-collapse: collapse; }
.cal-modal-table th { padding: 0 0 7px; text-align: center; font-size: 10px; font-weight: 500; color: var(--gray-400); }
.cm-day, .cm-empty { padding: 0; text-align: center; }
.cm-day-inner { display: flex; align-items: center; justify-content: center; width: 30px; height: 30px; margin: 2px auto; border-radius: 30px; font-size: 12px; font-weight: 450; color: var(--gray-700); transition: all 0.15s ease; }
.cm-clickable { cursor: pointer; }
.cm-clickable .cm-day-inner:hover { background: var(--navy-light); color: var(--navy); }
.cm-selected .cm-day-inner { background: var(--navy); color: var(--white); font-weight: 600; }
.cm-in-range .cm-day-inner { background: var(--navy-light); color: var(--navy); border-radius: 0; }
.cm-range-start .cm-day-inner { background: var(--navy); color: var(--white); font-weight: 600; border-radius: 30px 0 0 30px; }
.cm-range-end .cm-day-inner { background: var(--navy); color: var(--white); font-weight: 600; border-radius: 0 30px 30px 0; }
.cm-range-start.cm-range-end .cm-day-inner { border-radius: 30px; }
.cm-disabled .cm-day-inner { color: var(--gray-300); cursor: default; }
.cm-weekend .cm-day-inner { color: var(--gray-300); }
.cal-modal-footer { margin-top: 8px; text-align: center; min-height: 18px; }
.cal-modal-info { font-size: 10px; color: var(--gray-400); }
.cal-trigger { display: flex; align-items: center; justify-content: space-between; width: 100%; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.06); color: rgba(255,255,255,0.65); padding: 5px 9px; border-radius: 5px; cursor: pointer; font-size: 11px; font-family: var(--font); transition: all var(--transition); line-height: 1.4; }
.cal-trigger:hover { background: rgba(255,255,255,0.12); color: var(--white); }
.cal-trigger-arrow { font-size: 9px; color: rgba(255,255,255,0.3); }

/* RESPONSIVE */
@media (max-width: 1200px) {
  .dashboard-grid-2 { grid-template-columns: 1fr; }
  .dashboard-grid-destaques { grid-template-columns: 1fr; }
}
@media (max-width: 900px) {
  .cards { grid-template-columns: repeat(2, 1fr); }
  .grid2 { grid-template-columns: 1fr; }
}
@media (max-width: 768px) {
  .topbar-right .btn-primary span { display: none; }
}
@media print {
  .sidebar, .topbar, .btn-primary, .btn-date-range, .toast, .person-selector, .cal-modal-overlay { display: none !important; }
  .main { margin-left: 0 !important; }
  .content { padding: 0; }
  .page { display: block !important; page-break-after: always; }
  .page:last-child { page-break-after: avoid; }
}

/* ── KPI CARDS ── */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 12px;
  margin-bottom: 14px;
}
.kpi-card {
  border-radius: var(--radius-md);
  padding: 16px 16px 14px;
  color: white;
  position: relative;
  overflow: hidden;
  min-height: 145px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  box-shadow: var(--shadow-md);
}
.kpi-card::before {
  content: '';
  position: absolute;
  top: -30px; right: -30px;
  width: 100px; height: 100px;
  border-radius: 50%;
  background: rgba(255,255,255,0.06);
  pointer-events: none;
}
.kpi-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 2px;
}
.kpi-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: rgba(255,255,255,0.65);
  line-height: 1.3;
  max-width: 70%;
}
.kpi-icon-wrap {
  width: 32px; height: 32px;
  background: rgba(255,255,255,0.12);
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  flex-shrink: 0;
}
.kpi-icon-wrap svg { color: rgba(255,255,255,0.85); }
.kpi-value-num {
  font-size: 38px;
  font-weight: 800;
  letter-spacing: -0.04em;
  color: white;
  line-height: 1;
  margin: 4px 0 2px;
}
.kpi-sparkline-wrap {
  flex: 1;
  display: flex;
  align-items: flex-end;
  margin: 2px 0;
  opacity: 0.55;
}
.kpi-sparkline-wrap svg { width: 100%; }
.kpi-trend {
  font-size: 10px;
  color: rgba(255,255,255,0.7);
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 2px;
}
.trend-up { color: #4ADE80; font-weight: 600; }
.trend-down { color: #FCA5A5; font-weight: 600; }
.trend-neutral { color: rgba(255,255,255,0.5); }

/* Eficiência card specifics */
.kpi-card-eficiencia {
  background: #071030 !important;
}
.kpi-progress-track {
  height: 6px;
  background: rgba(255,255,255,0.15);
  border-radius: 100px;
  overflow: hidden;
  margin: 6px 0 4px;
}
.kpi-progress-fill {
  height: 100%;
  border-radius: 100px;
  background: linear-gradient(90deg, #4ADE80, #22C55E);
  transition: width 0.6s ease;
}

/* ── STATUS DA OPERAÇÃO ── */
.status-layout {
  display: flex;
  align-items: center;
  gap: 20px;
}
.status-donut-wrap {
  flex-shrink: 0;
  width: 200px;
}
.status-legend-wrap {
  flex: 1;
}
.status-legend-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 0;
  border-bottom: 1px solid var(--gray-100);
}
.status-legend-item:last-child { border-bottom: none; }
.legend-dot {
  width: 10px; height: 10px;
  border-radius: 50%;
  flex-shrink: 0;
}
.legend-name {
  flex: 1;
  font-size: 12px;
  font-weight: 500;
  color: var(--gray-700);
}
.legend-val {
  font-size: 13px;
  font-weight: 700;
  color: var(--gray-900);
  font-variant-numeric: tabular-nums;
}
.legend-pct {
  font-size: 11px;
  color: var(--gray-400);
  width: 38px;
  text-align: right;
}

/* ── PERFORMANCE POR EMPRESA ── */
.perf-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid var(--gray-100);
}
.perf-item:last-child { border-bottom: none; }
.perf-company-icon {
  width: 28px; height: 28px;
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-size: 9px; font-weight: 800; color: white;
  flex-shrink: 0;
}
.perf-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--gray-800);
  width: 90px;
  flex-shrink: 0;
}
.perf-bar-wrap {
  flex: 1;
  height: 8px;
  background: var(--gray-100);
  border-radius: 100px;
  overflow: hidden;
}
.perf-bar-fill {
  height: 100%;
  border-radius: 100px;
  transition: width 0.6s ease;
}
.perf-pct {
  font-size: 13px;
  font-weight: 700;
  color: var(--gray-900);
  width: 40px;
  text-align: right;
  flex-shrink: 0;
}
.perf-trend {
  font-size: 10px;
  font-weight: 600;
  width: 42px;
  text-align: right;
  flex-shrink: 0;
}
.perf-trend.up { color: var(--green-mid); }
.perf-trend.down { color: var(--red); }

/* ── TOP PENDÊNCIAS ── */
.pend-item {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}
.pend-item:last-child { margin-bottom: 0; }
.pend-name {
  font-size: 11px;
  font-weight: 600;
  color: var(--gray-700);
  width: 100px;
  flex-shrink: 0;
}
.pend-bar-wrap {
  flex: 1;
  height: 10px;
  background: var(--gray-100);
  border-radius: 100px;
  overflow: hidden;
}
.pend-bar-fill {
  height: 100%;
  border-radius: 100px;
  transition: width 0.6s ease;
}
.pend-bar-fill.critico { background: #DC2626; }
.pend-bar-fill.atencao { background: #ED6C02; }
.pend-bar-fill.normal  { background: #1B1F5E; }
.pend-count {
  font-size: 13px;
  font-weight: 700;
  color: var(--gray-900);
  width: 28px;
  text-align: right;
  flex-shrink: 0;
}
.pend-badge {
  font-size: 10px;
  font-weight: 700;
  padding: 2px 7px;
  border-radius: 100px;
  width: 42px;
  text-align: center;
  flex-shrink: 0;
}
.pend-badge.critico { background: #FEE2E2; color: #DC2626; }
.pend-badge.atencao { background: #FFF3E0; color: #ED6C02; }
.pend-badge.normal  { background: var(--navy-light); color: #1B1F5E; }
.pend-legend {
  display: flex;
  gap: 14px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid var(--gray-100);
}
.pend-leg-item {
  font-size: 10px;
  font-weight: 600;
  display: flex;
  align-items: center;
  gap: 5px;
}
.pend-leg-dot {
  width: 8px; height: 8px;
  border-radius: 50%;
}

/* ── TENDÊNCIAS ── */
.tendencias-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.chart-sub-label {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--gray-400);
  margin-bottom: 6px;
}

/* ── DESTAQUES POR EMPRESA ── */
.destaques-carousel {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}
.destaque-card {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: box-shadow var(--transition);
  cursor: pointer;
}
.destaque-card:hover { box-shadow: var(--shadow-md); }
.destaque-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}
.destaque-icon {
  width: 24px; height: 24px;
  border-radius: 6px;
  display: flex; align-items: center; justify-content: center;
  font-size: 9px; font-weight: 800; color: white;
  flex-shrink: 0;
}
.destaque-company-name {
  font-size: 11px;
  font-weight: 700;
  color: var(--gray-800);
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.destaque-status {
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 2px 6px;
  border-radius: 100px;
  flex-shrink: 0;
}
.destaque-status.lider   { background: #DCFCE7; color: #166534; }
.destaque-status.atencao { background: #FEF9C3; color: #854D0E; }
.destaque-status.critico { background: #FEE2E2; color: #991B1B; }
.destaque-eficiencia {
  font-size: 30px;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--gray-900);
  line-height: 1;
  margin: 2px 0;
}
.destaque-eficiencia-label {
  font-size: 9px;
  color: var(--gray-400);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 4px;
}
.destaque-metrics {
  display: flex;
  gap: 10px;
}
.destaque-metric { flex: 1; }
