     1→/* ── SPARKLINE GENERATOR ── */
     2→function generateSparkline(values, color, w, h) {
     3→  w = w || 100; h = h || 36;
     4→  if (!values || values.length < 2) return '';
     5→  var min = Math.min.apply(Math, values);
     6→  var max = Math.max.apply(Math, values);
     7→  if (max === min) { min = 0; }
     8→  var range = max - min || 1;
     9→  var step = w / (values.length - 1);
    10→  var pts = values.map(function(v, i) {
    11→    return (i * step).toFixed(1) + ',' + (h - ((v - min) / range * h)).toFixed(1);
    12→  }).join(' ');
    13→  return '<svg width="' + w + '" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '" xmlns="http://www.w3.org/2000/svg" style="display:block">' +
    14→    '<polyline points="' + pts + '" fill="none" stroke="' + color + '" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>' +
    15→    '</svg>';
    16→}
    17→
    18→/* ── TREND CALCULATION ── */
    19→function calcTrend(current, previous) {
    20→  if (!previous || previous === 0) return null;
    21→  var diff = current - previous;
    22→  var pct = ((diff / previous) * 100).toFixed(1);
    23→  return { diff: diff, pct: parseFloat(pct), positive: diff >= 0 };
    24→}
    25→
    26→function renderTrendHTML(trend, invertGood) {
    27→  if (!trend) return '<span class="trend-neutral">— vs período anterior</span>';
    28→  var isGood = invertGood ? !trend.positive : trend.positive;
    29→  var cls = isGood ? 'trend-up' : 'trend-down';
    30→  var arrow = trend.positive ? '▲' : '▼';
    31→  var abs = Math.abs(trend.pct);
    32→  return '<span class="' + cls + '">' + arrow + ' ' + abs + '%</span> vs período anterior';
    33→}
