    70→      line: { color: '#FF6B35', width: 2 }, marker: { color: '#FF6B35', size: 4 },
    71→      hovertemplate: '%{y}<extra>Robô</extra>' },
    72→    { x: labels, y: prenota, name: 'Pré-Nota', type: 'scatter', mode: 'lines+markers',
    73→      line: { color: '#ED6C02', width: 2 }, marker: { color: '#ED6C02', size: 4 },
    74→      hovertemplate: '%{y}<extra>Pré-Nota</extra>' }
    75→  ], lineLayout, { displayModeBar: false, responsive: true });
    76→
    77→  Plotly.newPlot('g_tendencias_pct', [
    78→    { x: labels, y: eficPct, name: 'Efic. Robô %', type: 'scatter', mode: 'lines+markers',
    79→      line: { color: '#2E7D32', width: 2 }, marker: { color: '#2E7D32', size: 4 },
    80→      hovertemplate: '%{y}%<extra>Efic. Robô</extra>' },
    81→    { x: labels, y: prenotaPct, name: '% Pré-Nota', type: 'scatter', mode: 'lines+markers',
    82→      line: { color: '#7C3AED', width: 2, dash: 'dot' }, marker: { color: '#7C3AED', size: 4 },
    83→      hovertemplate: '%{y}%<extra>% Pré-Nota</extra>' }
    84→  ], Object.assign({}, lineLayout, {
    85→    yaxis: Object.assign({}, lineLayout.yaxis, { ticksuffix: '%', range: [0, 110] })
    86→  }), { displayModeBar: false, responsive: true });
    87→}
    88→
    89→/* ── COMPANY CHARTS ── */
    90→function atualizarGraficosEmpresa(emp, barId, pieId) {
    91→  if (!state.dados || !state.dados[emp]) return;
    92→  var d = state.dados[emp];
    93→  var gap = Math.max(0, d.monitor - d.robo);
    94→  var maxVal = Math.max(d.monitor, d.prenota, d.robo, gap, 1);
    95→
    96→  Plotly.newPlot(barId, [{
    97→    x: ['Monitor', 'Pré-nota', 'Robô', 'GAP'],
    98→    y: [d.monitor, d.prenota, d.robo, gap],
    99→    type: 'bar',
   100→    marker: { color: ['#2E7D32', '#ED6C02', '#FF6B35', '#DC2626'], line: { color: '#ffffff', width: 1 } },
   101→    text: [d.monitor, d.prenota, d.robo, gap],
   102→    textposition: 'outside',
   103→    textfont: { family: 'Inter, sans-serif', size: 11, color: '#334155' },
   104→    hovertemplate: '%{y} notas<extra>%{x}</extra>',
   105→    cliponaxis: false
   106→  }], Object.assign(barLayout(24, maxVal), { bargap: 0.4, plot_bgcolor: 'transparent', paper_bgcolor: 'transparent' }), { displayModeBar: false, responsive: true });
   107→
   108→  var labels = [], values = [], colors = [];
   109→  if (d.robo > 0)   { labels.push('Escriturado pelo robô'); values.push(d.robo);   colors.push('#FF6B35'); }
   110→  if (gap > 0)      { labels.push('Pendentes (GAP)');       values.push(gap);       colors.push('#DC2626'); }
   111→  if (d.prenota > 0){ labels.push('Pré-nota');              values.push(d.prenota); colors.push('#ED6C02'); }
   112→  if (labels.length === 0) { labels.push('Sem dados'); values.push(1); colors.push('#D1D5DB'); }
   113→
   114→  Plotly.newPlot(pieId, [{
   115→    labels: labels, values: values, type: 'pie',
   116→    textinfo: 'label+percent',
   117→    textfont: { family: 'Inter, sans-serif', size: 10, color: '#334155' },
   118→    marker: { colors: colors, line: { color: '#ffffff', width: 2 } },
   119→    hole: 0.45,
   120→    hovertemplate: '%{label}: %{value} notas (%{percent})<extra></extra>',
   121→    sort: false, direction: 'clockwise', rotation: 90
   122→  }], {
   123→    margin: { t: 8, l: 8, r: 8, b: 50 },
   124→    showlegend: true,
   125→    legend: { orientation: 'h', y: -0.18, font: { family: 'Inter, sans-serif', size: 10, color: '#64748B' } },
   126→    font: CHART_FONT,
   127→    paper_bgcolor: CHART_BG,
   128→    hoverlabel: { bgcolor: '#1E293B', font: { family: 'Inter, sans-serif', size: 11, color: '#fff' } }
   129→  }, { displayModeBar: false, responsive: true });
   130→}
   131→
   132→function atualizarGraficosMaas() {
   133→  if (!state.dados || !state.dados['maas']) return;
   134→  var personId = getMaasPersona();
   135→
   136→  if (personId === 'all') {
   137→    atualizarGraficosEmpresa('maas', 'maas_bar', 'maas_pie');
   138→  } else {
   139→    var personData = getDadosMaasPorPessoa(state.dados, personId);
   140→    var p = getCompany('maas');
   141→    var person = p.responsaveis.find(function(r) { return r.id === personId; }) || p.responsaveis[0];
   142→    var gap = Math.max(0, personData.monitor - personData.robo);
   143→    var maxVal = Math.max(personData.monitor, personData.prenota, personData.robo, gap, 1);
   144→
   145→    Plotly.newPlot('maas_bar', [{
   146→      x: ['Monitor', 'Pré-nota', 'Robô', 'GAP'],
   147→      y: [personData.monitor, personData.prenota, personData.robo, gap],
   148→      type: 'bar',
   149→      marker: { color: [person.cor, '#ED6C02', '#FF6B35', '#DC2626'], line: { color: '#ffffff', width: 1 } },
   150→      text: [personData.monitor, personData.prenota, personData.robo, gap],
   151→      textposition: 'outside',
   152→      textfont: { family: 'Inter, sans-serif', size: 11, color: '#334155' },
   153→      hovertemplate: '%{y} notas<extra>%{x}</extra>',
   154→      cliponaxis: false
   155→    }], Object.assign(barLayout(24, maxVal), { bargap: 0.4, paper_bgcolor: CHART_BG }), { displayModeBar: false, responsive: true });
   156→
   157→    var labels = [], values = [], colors = [];
   158→    if (personData.robo > 0)   { labels.push('Escriturado pelo robô'); values.push(personData.robo);   colors.push('#FF6B35'); }
   159→    if (gap > 0)               { labels.push('Pendentes (GAP)');       values.push(gap);               colors.push('#DC2626'); }
   160→    if (personData.prenota > 0){ labels.push('Pré-nota');              values.push(personData.prenota); colors.push('#ED6C02'); }
   161→    if (labels.length === 0)   { labels.push('Sem dados'); values.push(1); colors.push('#D1D5DB'); }
   162→
   163→    Plotly.newPlot('maas_pie', [{
   164→      labels: labels, values: values, type: 'pie',
   165→      textinfo: 'label+percent',
   166→      textfont: { family: 'Inter, sans-serif', size: 10, color: '#334155' },
   167→      marker: { colors: colors, line: { color: '#ffffff', width: 2 } },
   168→      hole: 0.45,
   169→      hovertemplate: '%{label}: %{value} notas (%{percent})<extra></extra>',
   170→      sort: false, direction: 'clockwise', rotation: 90
   171→    }], {
   172→      margin: { t: 8, l: 8, r: 8, b: 50 },
   173→      showlegend: true,
   174→      legend: { orientation: 'h', y: -0.18, font: { family: 'Inter, sans-serif', size: 10, color: '#64748B' } },
   175→      font: CHART_FONT, paper_bgcolor: CHART_BG,
   176→      hoverlabel: { bgcolor: '#1E293B', font: { family: 'Inter, sans-serif', size: 11, color: '#fff' } }
   177→    }, { displayModeBar: false, responsive: true });
   178→  }
   179→
   180→  atualizarGraficosMaasComparativo();
   181→}
   182→
   183→function atualizarGraficosMaasComparativo() {
   184→  if (!state.dados || !state.dados['maas']) return;
   185→  var p = getCompany('maas');
   186→  var person1 = getDadosMaasPorPessoa(state.dados, 'responsavel1');
   187→  var person2 = getDadosMaasPorPessoa(state.dados, 'responsavel2');
   188→  var maxVal = Math.max(person1.monitor, person1.prenota, person1.robo, person2.monitor, person2.prenota, person2.robo, 1);
   189→
   190→  Plotly.newPlot('maas_person_bar', [
   191→    { x: ['Monitor', 'Pré-nota', 'Robô'], y: [person1.monitor, person1.prenota, person1.robo],
   192→      name: p.responsaveis[0].nome, type: 'bar',
   193→      marker: { color: p.responsaveis[0].cor, line: { color: '#ffffff', width: 1 } },
   194→      hovertemplate: '%{y}<extra>' + p.responsaveis[0].nome + '</extra>' },
   195→    { x: ['Monitor', 'Pré-nota', 'Robô'], y: [person2.monitor, person2.prenota, person2.robo],
   196→      name: p.responsaveis[1].nome, type: 'bar',
   197→      marker: { color: p.responsaveis[1].cor, line: { color: '#ffffff', width: 1 } },
   198→      hovertemplate: '%{y}<extra>' + p.responsaveis[1].nome + '</extra>' }
   199→  ], Object.assign(barLayout(14, maxVal), {
   200→    barmode: 'group', showlegend: true,
   201→    legend: { orientation: 'h', y: 1.12, font: { family: 'Inter, sans-serif', size: 10, color: '#64748B' } },
   202→    bargroupgap: 0.25, paper_bgcolor: CHART_BG
   203→  }), { displayModeBar: false, responsive: true });
   204→
   205→  Plotly.newPlot('maas_person_pie', [{
   206→    labels: [p.responsaveis[0].nome, p.responsaveis[1].nome],
   207→    values: [person1.total, person2.total],
   208→    type: 'pie', textinfo: 'label+percent',
   209→    textfont: { family: 'Inter, sans-serif', size: 10, color: '#334155' },
   210→    marker: { colors: [p.responsaveis[0].cor, p.responsaveis[1].cor], line: { color: '#ffffff', width: 2 } },
   211→    hole: 0.45,
   212→    hovertemplate: '%{label}: %{value} notas (%{percent})<extra></extra>',
   213→    sort: false, direction: 'clockwise', rotation: 90
   214→  }], {
   215→    margin: { t: 8, l: 8, r: 8, b: 50 },
   216→    showlegend: true,
   217→    legend: { orientation: 'h', y: -0.18, font: { family: 'Inter, sans-serif', size: 10, color: '#64748B' } },
   218→    font: CHART_FONT, paper_bgcolor: CHART_BG,
   219→    hoverlabel: { bgcolor: '#1E293B', font: { family: 'Inter, sans-serif', size: 11, color: '#fff' } }
   220→  }, { displayModeBar: false, responsive: true });
   221→}
